<?php
require_once __DIR__ . '/funktiot.php';
startApplicationSession();
$csrf = getApplicationCsrfToken(); $name = trim((string) ($_POST['name'] ?? '')); $phone = trim((string) ($_POST['phone'] ?? '')); $email = strtolower(trim((string) ($_POST['email'] ?? ''))); $company = trim((string) ($_POST['company'] ?? '')); $businessId = trim((string) ($_POST['business_id'] ?? '')); $contactMessage = trim((string) ($_POST['message'] ?? '')); $notice = ''; $noticeType = 'info';
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    if (!hash_equals($csrf, (string) ($_POST['csrf_token'] ?? ''))) { $notice = 'Pyyntö vanheni. Lataa sivu uudelleen ja yritä uudestaan.'; $noticeType = 'danger';
    } elseif ($name === '' || $phone === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || $contactMessage === '') { $notice = 'Täytä nimi, puhelin, sähköposti ja viesti.'; $noticeType = 'danger';
    } elseif (sendServiceRequest($name, $phone, $email, $company, $businessId, $contactMessage)) { $notice = 'Viestisi lähetettiin. Palaamme asiaan mahdollisimman pian.'; $noticeType = 'success'; $contactMessage = '';
    } else { $notice = 'Viestin lähetys epäonnistui. Yritä myöhemmin uudelleen.'; $noticeType = 'danger'; }
}
function contactEscape(string $value): string { return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); }
?><!doctype html><html lang="fi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Ota yhteyttä – TEKRAPORTTI</title><link rel="icon" type="image/png" href="Logo pyöreä.png"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f8fc;color:#071a3d;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.header{padding:20px 36px;background:#fff;border-bottom:1px solid #dce6f1}.header img{width:250px;max-width:70vw}.card{max-width:760px;margin:45px auto;padding:40px 48px;background:#fff;border:1px solid #dce6f1;border-radius:12px;box-shadow:0 8px 22px #1a345612}.card h1{margin:25px 0 8px}.lead{color:#52627a}.card label{font-weight:600;font-size:.9rem}.back{color:#1769e8;text-decoration:none;font-weight:600}@media(max-width:600px){.card{margin:18px 12px;padding:28px 22px}.header{padding:18px}}</style></head><body><header class="header"><a href="index.php"><img src="Logo.png" alt="TEKRAPORTTI"></a></header><main class="card"><a class="back" href="index.php">← Takaisin etusivulle</a><h1>Ota yhteyttä</h1><p class="lead">Lähetä viesti asiakaspalvelulle.</p><?php if ($notice !== ''): ?><div class="alert alert-<?= contactEscape($noticeType) ?>" role="alert"><?= contactEscape($notice) ?></div><?php endif; ?><form method="post" action="yhteydenotto.php"><input type="hidden" name="csrf_token" value="<?= contactEscape($csrf) ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="name">Nimi</label><input class="form-control" id="name" name="name" value="<?= contactEscape($name) ?>" maxlength="200" required></div><div class="col-md-6"><label class="form-label" for="phone">Puhelin</label><input class="form-control" id="phone" name="phone" value="<?= contactEscape($phone) ?>" maxlength="50" required></div><div class="col-md-6"><label class="form-label" for="email">Sähköposti</label><input type="email" class="form-control" id="email" name="email" value="<?= contactEscape($email) ?>" maxlength="254" required></div><div class="col-md-6"><label class="form-label" for="company">Yrityksen nimi</label><input class="form-control" id="company" name="company" value="<?= contactEscape($company) ?>" maxlength="200"></div><div class="col-md-6"><label class="form-label" for="business-id">Y-tunnus</label><input class="form-control" id="business-id" name="business_id" value="<?= contactEscape($businessId) ?>" maxlength="20"></div><div class="col-12"><label class="form-label" for="message">Viesti</label><textarea class="form-control" id="message" name="message" rows="6" maxlength="5000" required><?= contactEscape($contactMessage) ?></textarea></div></div><button class="btn btn-primary mt-3" type="submit">Lähetä viesti</button></form></main></body></html>
